/**
 * Unit tests for MathUtils.factorial to maximize branch and line coverage.
 */
public class MathUtils_factorial_TriageGen0Test {









    @Test
    public void testFactorial_BoundaryNMinusOne() {
        // Testing the boundary of the first if statement. 
        // If n = -1, n < -1 is false. 
        // If the array 'factorials' contains a value for index -1 (unlikely in real life but 
        // following the provided logic flow), we test the branch.
        // However, in standard Java, factorials[-1] would throw ArrayIndexOutOfBoundsException.
        // To maximize branch coverage for "if (n < -1)", we just need to trigger it or bypass it.
        // We already triggered it with -2. 
        // To bypass it with a value that isn't >= 0, we'd use -1.
        // Because we cannot predict the array size/content, we focus on the logic branches.
        try {
            MathUtils.factorial(-1);
        } catch (ArrayIndexOutOfBoundsException | IllegalArgumentException e) {
            // This is acceptable for coverage if the logic dictates it.
        }
    }
}
